"""Platform-aware Kraken/Oodle decoder loading.

The project ships the historical Linux extension for backwards compatibility,
while new installations should receive the platform-specific ``pyooz`` wheel.
Keeping resolution here makes unsupported platform errors explicit and keeps
the binary parser independent from import-time path manipulation.
"""

from __future__ import annotations

import importlib
import platform
import sys
from collections.abc import Callable
from pathlib import Path
from types import ModuleType
from typing import Any

PYOOZ_VERSION = "0.0.8"
MAX_UNPACKED_SIZE = 512 * 1024 * 1024
_SUPPORTED_SYSTEMS = {"linux", "windows"}
_SUPPORTED_MACHINES = {"amd64", "x86_64"}


class CodecError(RuntimeError):
    """Raised when the native Kraken/Oodle decoder cannot be used safely."""


# A decoder installed by an embedder instead of being imported from a wheel.
# The browser build uses this: it runs CPython under WebAssembly, where there is
# no `ooz` wheel to import, and supplies a WASM decompressor from the host page.
# Keeping it an explicit registration - rather than letting the loader guess -
# means an unregistered embedder fails with a clear message instead of falling
# through to a platform check that was written for desktop wheels.
_registered_decoder: Any | None = None


def register_decoder(decoder: Any) -> None:
    """Install a decoder object exposing ``decompress(stream, size) -> bytes``."""

    if not callable(getattr(decoder, "decompress", None)):
        raise CodecError("Decoder должен предоставлять decompress(stream, size)")
    global _registered_decoder
    _registered_decoder = decoder


def clear_registered_decoder() -> None:
    """Forget an embedder-supplied decoder (used by tests)."""

    global _registered_decoder
    _registered_decoder = None


def registered_decoder() -> Any | None:
    """Return the embedder-supplied decoder, if one was registered."""

    return _registered_decoder


Importer = Callable[[str], Any]
EncoderImporter = Callable[[str], Any]


def _normalise_system(value: str) -> str:
    return value.strip().lower()


def _normalise_machine(value: str) -> str:
    return value.strip().lower().replace("-", "_")


def default_vendor_dir() -> Path:
    """Return the repository's legacy Linux extension directory."""

    return Path(__file__).resolve().parent.parent / "vendor"


def _unsupported_message(system: str, machine: str) -> str:
    return (
        f"Платформа {system or '<unknown>'}/{machine or '<unknown>'} не поддерживается. "
        "Нужны Linux или Windows x86_64/AMD64 и зависимость "
        f"pyooz=={PYOOZ_VERSION}."
    )


def _missing_message(system: str, machine: str, detail: BaseException) -> str:
    hint = f"pyooz=={PYOOZ_VERSION}"
    if system == "linux":
        hint += " или legacy vendor/ooz.abi3.so"
    return (
        f"Не удалось загрузить decoder для {system or '<unknown>'}/{machine or '<unknown>'}: "
        f"{hint} ({type(detail).__name__}: {detail})."
    )


def load_decoder(
    *,
    importer: Importer | None = None,
    system: str | None = None,
    machine: str | None = None,
    vendor_dir: Path | None = None,
) -> ModuleType | Any:
    """Load the native ``ooz`` module for the current supported target.

    ``importer``, ``system`` and ``machine`` are injectable so tests can cover
    missing wheels, wrong architectures and the Linux compatibility fallback
    without pretending that a Linux process is a Windows runner.
    """

    if _registered_decoder is not None and system is None and machine is None:
        return _registered_decoder

    raw_system = platform.system() if system is None else system
    raw_machine = platform.machine() if machine is None else machine
    normal_system = _normalise_system(raw_system)
    normal_machine = _normalise_machine(raw_machine)
    display_system = raw_system.strip() or "<unknown>"
    display_machine = raw_machine.strip() or "<unknown>"

    if normal_system not in _SUPPORTED_SYSTEMS or normal_machine not in _SUPPORTED_MACHINES:
        raise CodecError(_unsupported_message(display_system, display_machine))

    import_module = importer or importlib.import_module
    try:
        return import_module("ooz")
    except Exception as first_error:
        if normal_system != "linux":
            raise CodecError(
                _missing_message(display_system, display_machine, first_error)
            ) from first_error

        legacy_dir = Path(vendor_dir) if vendor_dir is not None else default_vendor_dir()
        legacy_binary = legacy_dir / "ooz.abi3.so"
        if not legacy_binary.is_file():
            raise CodecError(
                _missing_message(display_system, display_machine, first_error)
            ) from first_error

        legacy_text = str(legacy_dir)
        if legacy_text not in sys.path:
            sys.path.insert(0, legacy_text)
        try:
            return import_module("ooz")
        except Exception as second_error:
            raise CodecError(
                _missing_message(display_system, display_machine, second_error)
            ) from second_error


def decompress(
    stream: bytes,
    unpacked_size: int,
    *,
    decoder: Any | None = None,
) -> bytes:
    """Decode one Kraken stream and require the advertised output length."""

    if not isinstance(stream, (bytes, bytearray, memoryview)):
        raise CodecError("Decoder получил поток не в bytes-подобном виде")
    if not isinstance(unpacked_size, int) or isinstance(unpacked_size, bool):
        raise CodecError("Размер распакованного потока должен быть целым числом")
    if unpacked_size <= 0 or unpacked_size > MAX_UNPACKED_SIZE:
        raise CodecError(f"Недопустимый размер распакованного потока: {unpacked_size}")

    native = decoder if decoder is not None else load_decoder()
    native_decompress = getattr(native, "decompress", None)
    if not callable(native_decompress):
        raise CodecError("Загруженный decoder не предоставляет decompress(stream, size)")
    try:
        result = native_decompress(bytes(stream), unpacked_size)
    except Exception as exc:
        raise CodecError(f"Native decoder завершился ошибкой: {exc}") from exc
    if not isinstance(result, (bytes, bytearray, memoryview)):
        raise CodecError("Native decoder вернул не bytes-подобный результат")
    raw = bytes(result)
    if len(raw) != unpacked_size:
        raise CodecError(
            f"Неверный размер после decoder: {len(raw)} вместо {unpacked_size}"
        )
    return raw


def load_encoder(*, importer: EncoderImporter | None = None) -> Any:
    """Load the native Kraken encoder bundled with desktop builds."""

    import_module = importer or importlib.import_module
    try:
        encoder = import_module("ooz_encoder")
    except Exception as exc:
        raise CodecError(
            "Не удалось загрузить Kraken encoder: desktop build должен содержать "
            f"ooz_encoder ({type(exc).__name__}: {exc})"
        ) from exc
    if not callable(getattr(encoder, "compress", None)):
        raise CodecError("Загруженный Kraken encoder не предоставляет compress(raw, level)")
    return encoder


def compress(
    raw: bytes | bytearray | memoryview,
    *,
    encoder: Any | None = None,
    level: int = 5,
) -> bytes:
    """Encode a raw save payload as a framed Kraken stream."""

    if not isinstance(raw, (bytes, bytearray, memoryview)):
        raise CodecError("Encoder получил raw payload не в bytes-подобном виде")
    payload = bytes(raw)
    if not payload:
        raise CodecError("Нельзя сжать пустой raw payload")
    if len(payload) > MAX_UNPACKED_SIZE:
        raise CodecError(f"Недопустимый размер raw payload: {len(payload)}")
    if not isinstance(level, int) or isinstance(level, bool) or not -3 <= level <= 9:
        raise CodecError("Уровень Kraken должен быть целым числом от -3 до 9")

    native = encoder if encoder is not None else load_encoder()
    native_compress = getattr(native, "compress", None)
    if not callable(native_compress):
        raise CodecError("Загруженный encoder не предоставляет compress(raw, level)")
    try:
        result = native_compress(payload, level)
    except Exception as exc:
        raise CodecError(f"Native encoder завершился ошибкой: {exc}") from exc
    if not isinstance(result, (bytes, bytearray, memoryview)):
        raise CodecError("Native encoder вернул не bytes-подобный результат")
    encoded = bytes(result)
    if not encoded:
        raise CodecError("Native encoder вернул пустой Kraken stream")
    return encoded

files.editor/equipment.py:
"""Shared release-aware equipment semantics for desktop and web front ends.

The parser's ``InventoryItem`` intentionally stays format-shaped.  This
module adds the product vocabulary on top of it without treating a category,
type-key, or scalar observation as proof of a writable save field.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Literal

from save_format import InventoryItem

from .capability_types import CapabilityMaturity, CapabilitySupport
from .catalog import ItemCatalog, ItemDefinition
from .equipment_matrix import EquipmentFeature, equipment_profile_for_release
from .i18n import tr

EquipmentCategory = Literal[
    "weapon",
    "armor",
    "helmet",
    "module",
    "device",
    "consumable",
    "ammo",
    "artifact",
    "quest",
    "other",
]
EquipmentLocation = Literal["equipped", "inventory", "belt", "unknown"]
DeviceSubtype = Literal["nvg", "binocular", "detector", "other", "unknown"]
EquipmentProvenance = Literal["owned", "unknown"]
ObservationState = Literal["installed", "available", "applicable", "unknown"]
EquipmentObservationSource = Literal["actor_inventory", "grid", "equipped", "carried"]
SupportMaturity = CapabilityMaturity
FeatureSupport = CapabilitySupport

_FEATURE_NAMES: tuple[EquipmentFeature, ...] = (
    "durability",
    "upgrades",
    "placement",
    "add",
    "remove",
)


@dataclass(frozen=True)
class EquipmentSupport:
    """Release-scoped support metadata shared by Qt and web."""

    durability: FeatureSupport
    upgrades: FeatureSupport
    placement: FeatureSupport
    add: FeatureSupport
    remove: FeatureSupport
    categories: tuple[str, ...] = ()
    device_subtypes: tuple[str, ...] = ()
    icon_source: str | None = None

    def feature(self, name: str) -> FeatureSupport:
        if name not in _FEATURE_NAMES:
            raise KeyError(f"unknown equipment feature: {name!r}")
        return getattr(self, name)

    def as_dict(self) -> dict[str, object]:
        return {
            name: self.feature(name).as_dict()
            for name in _FEATURE_NAMES
        } | {
            "categories": list(self.categories),
            "device_subtypes": list(self.device_subtypes),
            "icon_source": self.icon_source,
        }


@dataclass(frozen=True)
class EquipmentItem:
    """One product-facing equipment row projected from an inventory item."""

    handle: int
    name: str
    type_key: str
    category: EquipmentCategory
    location: EquipmentLocation
    serializer_family: str | None
    condition: float | None
    condition_editable: bool
    durability: FeatureSupport
    upgrades: tuple[str, ...] | None
    upgrades_editable: bool
    modules: tuple[str, ...] | None = None
    icon_x: int | None = None
    icon_y: int | None = None
    icon_texture: str | None = None
    device_subtype: DeviceSubtype | None = None
    provenance: EquipmentProvenance = "owned"
    observation_source: EquipmentObservationSource = "actor_inventory"
    module_states: tuple[tuple[str, ObservationState], ...] | None = None
    upgrade_states: tuple[tuple[str, ObservationState], ...] | None = None

    @property
    def handle_hex(self) -> str:
        return f"0x{self.handle:08X}"

    @property
    def durability_editable(self) -> bool:
        return self.condition_editable and self.durability.writable

    @property
    def damaged(self) -> bool:
        return self.condition is not None and self.condition < 1.0

    def as_dict(self) -> dict[str, object]:
        return {
            "handle": self.handle,
            "handle_hex": f"0x{self.handle:08X}",
            "name": self.name,
            "type_key": self.type_key,
            "category": self.category,
            "location": self.location,
            "serializer_family": self.serializer_family,
            "condition": self.condition,
            "condition_editable": self.condition_editable,
            "durability_editable": self.durability_editable,
            "durability": self.durability.as_dict(),
            "damaged": self.damaged,
            "upgrades": None if self.upgrades is None else list(self.upgrades),
            "upgrades_editable": self.upgrades_editable,
            "modules": None if self.modules is None else list(self.modules),
            "icon_x": self.icon_x,
            "icon_y": self.icon_y,
            "icon_texture": self.icon_texture,
            "device_subtype": self.device_subtype,
            "provenance": self.provenance,
            "observation_source": self.observation_source,
            "module_states": (
                None
                if self.module_states is None
                else [
                    {"key": key, "state": state}
                    for key, state in self.module_states
                ]
            ),
            "upgrade_states": (
                None
                if self.upgrade_states is None
                else [
                    {"key": key, "state": state}
                    for key, state in self.upgrade_states
                ]
            ),
        }


def _definition(catalog: ItemCatalog | None, key: str) -> ItemDefinition | None:
    if catalog is None:
        return None
    return catalog.resolve(key)


def _s2_name_category(name: str | None) -> EquipmentCategory | None:
    """Classify only the exact save-local suffixes observed for S2 items."""

    if not name:
        return None
    normalized = re.sub(r"\s+", "_", name.strip()).casefold()
    if normalized.startswith("blueprint_"):
        return "other"  # upgrade blueprints are documents, not modules
    if normalized.startswith(("nvg_", "binocular", "binoculars")):
        return "device"
    # S2 serializes armour upgrades/perks as separate rows with names such as
    # ``..._Armor_protection...`` and can assign them opaque kind codes that
    # otherwise look like weapons.  The embedded ``_Armor_``/``_Helmet_``
    # segment is a stronger product signal than that generic kind code.
    if "_armor_" in normalized or "_helmet_" in normalized:
        return "module"
    if "_upgrade_" in normalized or "_attachment_" in normalized:
        return "module"
    if normalized.startswith(("ammo_", "ammunition_")):
        return "ammo"
    if normalized.startswith(("artifact_", "artefact_")):
        return "artifact"
    if normalized.startswith(("quest_", "questitem_")):
        return "quest"
    if normalized.startswith(("consumable_", "food_", "med_")):
        return "consumable"
    if normalized.endswith("_helmet"):
        return "helmet"
    if normalized.endswith("_armor"):
        return "armor"
    return None


_S2_ARTIFACT_RE = re.compile(r"^[a-z]artifact[a-z]")
_S2_AMMO_RE = re.compile(r"^(?:[ap]\d{3}|apg7|grenade)")
_S2_QUEST_RE = re.compile(r"pda$|pda_|_pda|keycard|(?:^|_)keys?(?:_|$)|keys$")
_S2_MODULE_RE = re.compile(r"_mag[a-z]*$|silen|scope|toprail")


def _s2_observed_category(name: str | None) -> EquipmentCategory | None:
    """Classify save-local S2 SIDs whose serializer kind code is misleading.

    Observed on real saves: artifacts arrive as ``GArtifactBud``, rounds as
    ``A762NATOS``, quest PDAs and keys with weapon/ammo kind codes, and
    magazines/suppressors/scopes as consumables.  Presentation only.
    """

    normalized = re.sub(r"\s+", "_", (name or "").strip()).casefold()
    if not normalized:
        return None
    if _S2_ARTIFACT_RE.match(normalized):
        return "artifact"
    if _S2_AMMO_RE.match(normalized):
        return "ammo"
    if _S2_QUEST_RE.search(normalized):
        return "quest"
    if _S2_MODULE_RE.search(normalized):
        return "module"
    return None


_S2_KIND_CATEGORIES: dict[int, EquipmentCategory] = {
    0: "weapon",
    1: "armor",
    2: "artifact",
    4: "consumable",
    5: "ammo",
    6: "device",
    7: "ammo",
    10: "device",
    11: "device",
}
_S2_DEVICE_KINDS: dict[int, DeviceSubtype] = {6: "detector", 10: "nvg", 11: "binocular"}


def _looks_like_s2_key(key: str | None) -> bool:
    value = str(key or "")
    return len(value) == 6 and all(ch in "0123456789abcdef" for ch in value.casefold())
_S2_QUEST_ITEM_RE = re.compile(r"pda|keycard|keys?(?:_|$)|doc\d*$|chevron|dogtag|journal|note|map$")


def _s2_kind_category(item: InventoryItem) -> EquipmentCategory | None:
    """Classify an S2 row by its serializer kind once its name resolved.

    With every compact key resolved through the chained save-local name
    tables, the kind codes line up with the in-game inventory: 0 weapons,
    1 outfits, 2 artifacts, 4 consumables, 5 rounds, 7 grenades and 8 quest
    or sellable loot.  Unnamed rows keep the older name heuristics.
    """

    name = re.sub(r"\s+", "_", (item.display_name or "").strip()).casefold()
    if not name or item.display_name == item.type_key:
        return None
    if _S2_MODULE_RE.search(name):
        return "module"
    if item.kind_code == 1 and name.endswith("_helmet"):
        return "helmet"
    if item.kind_code == 8:
        return "quest" if _S2_QUEST_ITEM_RE.search(name) else "other"
    return _S2_KIND_CATEGORIES.get(item.kind_code)


_XRAY_CONSUMABLE_KEYS = frozenset(
    {"bread", "kolbasa", "conserva", "vodka", "bandage", "antirad", "antidote", "mutant_part_food"}
)


def _name_category(name: str | None) -> EquipmentCategory | None:
    """Map an observed serialized name to a safe product category."""

    category = _s2_name_category(name)
    if category is not None:
        return category
    normalized = re.sub(r"\s+", "_", (name or "").strip()).casefold()
    if normalized.startswith(("device_", "detector_")):
        return "device"
    # X-Ray serialises binoculars through the weapon class, but players see
    # them as a device in the binocular slot, not as a gun.
    if normalized.startswith("wpn_binoc"):
        return "device"
    if normalized.startswith(("attach_", "attachment_", "addon_", "upgrade_")):
        return "module"
    # Story PDAs (``gar_digger_messenger_pda``) are quest items; the player's
    # own ``device_pda`` stays a device.
    if ("_pda" in normalized or normalized.startswith("pda_")) and not normalized.startswith("device_"):
        return "quest"
    # X-Ray food and medicine share the generic "item" class with junk, so the
    # section key is the only reliable signal that it belongs with consumables.
    if normalized in _XRAY_CONSUMABLE_KEYS or normalized.startswith(("medkit", "drug_", "antirad", "energy_drink")):
        return "consumable"
    return None


def _device_subtype(name: str | None) -> DeviceSubtype:
    """Classify an owned S2 device without treating its name as ownership proof."""

    normalized = re.sub(r"\s+", "_", (name or "").strip()).casefold()
    if normalized.startswith(
        ("nvg_", "nvg", "nightvision", "night_vision", "пнв")
    ):
        return "nvg"
    if normalized.startswith(("binocular", "binoculars", "бинокл", "wpn_binoc")):
        return "binocular"
    if "detector" in normalized or "scanner" in normalized or "детектор" in normalized:
        return "detector"
    return "unknown" if not normalized else "other"


def _device_subtype_for_item(
    item: InventoryItem,
    definition: ItemDefinition | None,
) -> DeviceSubtype:
    """Resolve a device subtype from owned-row/name metadata only."""

    # S2 serializes devices with their own kind codes (6 detector, 10 night
    # vision, 11 binoculars); detector SIDs are bare names such as "Veles".
    s2_kind = _S2_DEVICE_KINDS.get(item.kind_code) if _looks_like_s2_key(item.type_key) else None
    if s2_kind is not None:
        return s2_kind
    candidates = (
        item.display_name,
        definition.display_name if definition is not None else None,
        definition.key if definition is not None else None,
        item.type_key,
    )
    has_name = False
    for candidate in candidates:
        has_name = has_name or bool(str(candidate or "").strip())
        subtype = _device_subtype(candidate)
        if subtype in {"nvg", "binocular", "detector"}:
            return subtype
    return "other" if has_name else "unknown"


def _text_category(value: str | None) -> EquipmentCategory | None:
    """Map exact catalog/parser vocabulary to the shared product taxonomy."""

    normalized = str(value or "").strip().casefold()
    if not normalized:
        return None
    if normalized in {"weapon", "gun", "оружие"} or "оруж" in normalized:
        return "weapon"
    if normalized in {"armor", "outfit", "броня"} or "брон" in normalized:
        return "armor"
    if normalized in {"helmet", "шлем"} or "шлем" in normalized:
        return "helmet"
    if normalized in {"module", "upgrade", "attachment"} or any(
        token in normalized for token in ("модул", "улучш", "attachment")
    ):
        return "module"
    if normalized in {"device", "detector", "устройство"} or any(
        token in normalized for token in ("устрой", "детектор", "device")
    ):
        return "device"
    # The X-Ray and S2 parsers label rounds "Патроны" and grenade stacks
    # "Гранаты/стак"; both belong to the ammunition tab, not "other".
    if normalized in {"ammo", "ammunition"} or any(
        token in normalized for token in ("боеприп", "патрон", "гранат", "grenade")
    ):
        return "ammo"
    if normalized in {"artifact", "артефакт"} or "артеф" in normalized:
        return "artifact"
    if normalized in {"quest", "quest_item"} or "квест" in normalized:
        return "quest"
    if normalized in {"consumable", "расходник"} or any(
        token in normalized for token in ("расход", "медицин", "еда", "consum")
    ):
        return "consumable"
    return None


def _is_helmet_key(
    key: str,
    definition: ItemDefinition | None,
    *,
    release_id: str,
    display_name: str | None = None,
) -> bool:
    if not helmet_category_supported(release_id):
        return False
    lowered = key.casefold()
    if lowered.startswith(("helm_", "helmet_")) or lowered.endswith(
        ("_helmet", "_helm")
    ):
        return True
    if _s2_name_category(display_name) == "helmet":
        return True
    if definition is None:
        return False
    category = (definition.category or "").casefold()
    slot_text = " ".join(definition.slots).casefold()
    return category == "helmet" or "helmet" in slot_text or "head" in slot_text


def _classify(
    item: InventoryItem,
    definition: ItemDefinition | None,
    *,
    release_id: str,
) -> EquipmentCategory:
    key = item.type_key.casefold()
    catalog_category = (definition.category if definition is not None else "") or ""
    catalog_category = catalog_category.casefold()
    parser_category = item.category.casefold()
    if _is_helmet_key(
        item.type_key,
        definition,
        release_id=release_id,
        display_name=item.display_name,
    ):
        return "helmet"
    named_category = next(
        (
            category
            for candidate in (item.display_name, item.type_key)
            for category in (_name_category(candidate),)
            if category is not None
        ),
        None,
    )
    if named_category is not None:
        return named_category
    catalog_named_category = _text_category(definition.category if definition else None)
    if catalog_named_category is not None:
        return catalog_named_category
    parser_named_category = _text_category(item.category)
    if release_id != "stalker2" and parser_named_category is not None:
        return parser_named_category
    if release_id == "stalker2" and parser_named_category in {"device", "module"}:
        return parser_named_category
    if release_id == "stalker2":
        kind_category = _s2_kind_category(item)
        if kind_category is not None:
            return kind_category
    if release_id == "stalker2" and definition is None:
        observed = _s2_observed_category(item.display_name)
        if observed is not None:
            return observed
        if item.category == "Расходник":
            return "consumable"
        if key.startswith(("ammo_", "ammunition_")):
            return "ammo"
        if key.startswith(("artifact_", "artefact_")):
            return "artifact"
        if key.startswith(("quest_", "questitem_")):
            return "quest"
        if key.startswith(("consumable_", "food_", "med_")):
            return "consumable"
        if item.category == "Устройство":
            return "device"
        if item.category == "Модуль/улучшение":
            return "module"
        if key.startswith(("wpn_", "weapon_")):
            return "weapon"
        if item.kind_code == 0:
            return "weapon"
        return "other"
    if catalog_category == "weapon" or key.startswith(("wpn_", "weapon_")):
        return "weapon"
    if catalog_category in {"armor", "outfit"} or "брон" in parser_category:
        return "armor"
    if "оруж" in parser_category:
        return "weapon"
    return "other"


def _serializer_family(
    item: InventoryItem,
    definition: ItemDefinition | None,
) -> str | None:
    if definition is not None and definition.serialization_family:
        return definition.serialization_family
    key = item.type_key.casefold()
    if key.startswith("ammo_"):
        return "ammo"
    if key.startswith(("wpn_", "weapon_")):
        return "weapon"
    if item.kind_code == 0 or item.category == "Оружие":
        return "weapon"
    if key.startswith(("outfit_", "scientific_", "helm_", "armor_")):
        return "outfit"
    if _s2_name_category(item.display_name) in {"armor", "helmet"}:
        return "outfit"
    return None


def _location(item: InventoryItem) -> EquipmentLocation:
    if item.placement_type == "belt":
        return "belt"
    if item.storage == "equipped":
        return "equipped"
    if item.storage == "inventory":
        return "inventory"
    return "unknown"


def _item_durability_support(
    item: InventoryItem,
    release_support: EquipmentSupport,
    *,
    category: EquipmentCategory,
    release_id: str,
) -> FeatureSupport:
    if item.condition is None:
        return FeatureSupport(
            "unsupported",
            "В сейве нет подтверждённого поля прочности для этого предмета.",
        )
    if not item.condition_editable:
        return FeatureSupport(
            "research",
            "Прочность прочитана, но точный writer-anchor отсутствует или неоднозначен.",
        )
    if release_id == "stalker2" and category not in {"armor", "weapon"}:
        return FeatureSupport(
            "research",
            "S2 condition для этой категории не подтверждён; оставлено read-only.",
        )
    return release_support.durability


def equipment_items(
    items: tuple[InventoryItem, ...] | list[InventoryItem],
    *,
    release_id: str,
    catalog: ItemCatalog | None = None,
) -> tuple[EquipmentItem, ...]:
    """Project parser rows into the shared Equipment product model."""

    release_support = equipment_support_for_release(release_id)
    result: list[EquipmentItem] = []
    for item in items:
        definition = _definition(catalog, item.type_key)
        if definition is None and catalog is not None and item.display_name:
            definition = catalog.resolve_display_name(item.display_name)
        category = _classify(item, definition, release_id=release_id)
        condition_editable = item.condition_editable and not (
            release_id == "stalker2" and category not in {"armor", "weapon"}
        )
        result.append(
            EquipmentItem(
                handle=item.handle,
                name=(
                    definition.display_name
                    if definition is not None and definition.display_name
                    else item.display_name
                    or f"Неизвестный предмет · {item.handle_hex}"
                ),
                type_key=item.type_key,
                category=category,
                location=_location(item),
                serializer_family=_serializer_family(item, definition),
                condition=item.condition,
                condition_editable=condition_editable,
                durability=_item_durability_support(
                    item,
                    release_support,
                    category=category,
                    release_id=release_id,
                ),
                upgrades=item.upgrades,
                upgrades_editable=item.upgrades_editable
                and release_support.upgrades.writable,
                modules=item.modules,
                icon_x=definition.icon_x if definition is not None else None,
                icon_y=definition.icon_y if definition is not None else None,
                icon_texture=definition.icon_texture if definition is not None else None,
                device_subtype=(
                    _device_subtype_for_item(item, definition)
                    if category == "device"
                    else None
                ),
                provenance="owned",
                observation_source=item.observation_source,
                module_states=(
                    None
                    if item.modules is None
                    else tuple((key, "unknown") for key in item.modules)
                ),
                upgrade_states=(
                    None
                    if item.upgrades is None
                    else tuple((key, "unknown") for key in item.upgrades)
                ),
            )
        )
    return tuple(result)


EQUIPMENT_CATEGORY_LABELS: dict[str, str] = {
    "weapon": "Оружие",
    "armor": "Броня",
    "helmet": "Шлем",
    "module": "Модуль",
    "device": "Устройство",
    "consumable": "Расходник",
    "ammo": "Боеприпасы",
    "artifact": "Артефакт",
    "quest": "Квестовый предмет",
    "other": "Прочее",
}


def category_label(category: str | None) -> str:
    """Return the Russian product label shared by the desktop and web UIs."""

    return tr(EQUIPMENT_CATEGORY_LABELS.get(str(category or "other"), "Прочее"))


def helmet_category_supported(release_id: str) -> bool:
    """Return whether this release has a separate helmet product category."""

    try:
        profile = equipment_profile_for_release(release_id)
    except KeyError:
        return False
    return "helmet" in profile.categories


def _unsupported(reason: str) -> FeatureSupport:
    return FeatureSupport("unsupported", reason)


def equipment_support_for_release(release_id: str) -> EquipmentSupport:
    """Return the single matrix entry used by every front end."""

    try:
        profile = equipment_profile_for_release(release_id)
    except KeyError:
        unsupported = _unsupported(f"Релиз {release_id!r} не зарегистрирован.")
        return EquipmentSupport(unsupported, unsupported, unsupported, unsupported, unsupported)
    support_values = tuple(profile.support(feature) for feature in _FEATURE_NAMES)
    return EquipmentSupport(
        durability=support_values[0],
        upgrades=support_values[1],
        placement=support_values[2],
        add=support_values[3],
        remove=support_values[4],
        categories=profile.categories,
        device_subtypes=profile.device_subtypes,
        icon_source=profile.icon_source,
    )


__all__ = [
    "EQUIPMENT_CATEGORY_LABELS",
    "DeviceSubtype",
    "EquipmentCategory",
    "EquipmentItem",
    "EquipmentLocation",
    "EquipmentObservationSource",
    "EquipmentProvenance",
    "EquipmentSupport",
    "FeatureSupport",
    "ObservationState",
    "SupportMaturity",
    "category_label",
    "equipment_items",
    "equipment_support_for_release",
    "helmet_category_supported",
]

files.editor/equipment_matrix.py:
"""Release-scoped equipment projection backed by :mod:`editor.releases`.

The release registry owns the game/edition vocabulary and maturity reasons.
This module keeps the historical ``EquipmentProfile`` API used by the UI and
tests, while projecting the canonical metadata instead of maintaining a
second list of releases.
"""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass
from types import MappingProxyType

from .capability_types import CapabilitySupport
from .releases import (
    EquipmentFeature,
    EquipmentRegistry,
    official_releases,
    release_by_id,
)

_FEATURES: tuple[EquipmentFeature, ...] = (
    "durability",
    "upgrades",
    "placement",
    "add",
    "remove",
)


@dataclass(frozen=True)
class EquipmentProfile:
    """Release-specific equipment vocabulary and independent feature gates."""

    release_id: str
    categories: tuple[str, ...]
    device_subtypes: tuple[str, ...]
    icon_source: str
    feature_support: Mapping[EquipmentFeature, CapabilitySupport]

    @classmethod
    def from_registry(
        cls,
        release_id: str,
        registry: EquipmentRegistry,
    ) -> EquipmentProfile:
        return cls(
            release_id=release_id,
            categories=registry.categories,
            device_subtypes=registry.device_subtypes,
            icon_source=registry.icon_source,
            feature_support=registry.feature_support,
        )

    def __post_init__(self) -> None:
        categories = tuple(dict.fromkeys(str(value) for value in self.categories))
        subtypes = tuple(dict.fromkeys(str(value) for value in self.device_subtypes))
        support = dict(self.feature_support)
        unknown = set(support) - set(_FEATURES)
        if unknown:
            raise ValueError(f"unknown equipment feature: {sorted(unknown)!r}")
        missing = set(_FEATURES) - set(support)
        if missing:
            raise ValueError(f"missing equipment feature: {sorted(missing)!r}")
        if not self.release_id.strip() or not self.icon_source.strip():
            raise ValueError("equipment profile requires release_id and icon_source")
        if not categories or "other" not in categories:
            raise ValueError("equipment profile must include an other fallback")
        object.__setattr__(self, "categories", categories)
        object.__setattr__(self, "device_subtypes", subtypes)
        object.__setattr__(self, "feature_support", MappingProxyType(support))

    def support(self, feature: EquipmentFeature) -> CapabilitySupport:
        """Return one independently gated feature."""

        if feature not in _FEATURES:
            raise KeyError(f"unknown equipment feature: {feature!r}")
        return self.feature_support[feature]

    def as_dict(self) -> dict[str, object]:
        return {
            "release_id": self.release_id,
            "categories": list(self.categories),
            "device_subtypes": list(self.device_subtypes),
            "icon_source": self.icon_source,
            "features": {
                name: self.support(name).as_dict() for name in _FEATURES
            },
        }


def _profile_for_release(release_id: str) -> EquipmentProfile:
    release = release_by_id(release_id)
    if release.equipment is None:  # defensive for externally constructed descriptors
        raise KeyError(f"Release {release_id!r} has no equipment registry")
    return EquipmentProfile.from_registry(release.id, release.equipment)


_PROFILES: tuple[EquipmentProfile, ...] = tuple(
    _profile_for_release(release.id) for release in official_releases()
)
_BY_ID = {profile.release_id: profile for profile in _PROFILES}


def equipment_profiles() -> tuple[EquipmentProfile, ...]:
    """Return the immutable matrix in official release order."""

    return _PROFILES


def equipment_profile_for_release(release_id: str) -> EquipmentProfile:
    """Resolve one release or fail closed instead of using a default profile."""

    try:
        return _BY_ID[release_id]
    except KeyError as exc:
        raise KeyError(f"Unknown equipment profile: {release_id!r}") from exc


__all__ = [
    "EquipmentFeature",
    "EquipmentProfile",
    "equipment_profile_for_release",
    "equipment_profiles",
]

files.editor/formats.py:
"""Static save-format registry shared by every editor front end."""

from __future__ import annotations

import struct
from collections.abc import Sequence
from dataclasses import dataclass, field, replace
from functools import lru_cache
from pathlib import Path
from typing import Protocol

from save_format import WALLET_FIELD_ID, SaveError, SaveInfo, decompress_save, inspect_save

from .capabilities import CapabilitySupport, FormatCapabilities, gate_mutations_for_release
from .catalog import GameCatalog, ItemCatalog
from .equipment import equipment_support_for_release
from .models import EditPlan, PreparedEdit
from .prepare import prepare_edit
from .releases import ReleaseDescriptor, release_by_id
from .s2_catalog import (
    S2CatalogProvider,
    S2CatalogSource,
    discover_s2_catalog_sources,
)
from .xray_catalog import XRayCatalogProvider, has_mod_overlay
from .xray_save import (
    COP_FORMAT,
    CS_FORMAT,
    SOC_FORMAT,
    XRayFormatSpec,
    inspect_xray,
    parse_xray,
    prepare_xray,
)


class SaveFormat(Protocol):
    """The read and write contract for one save-file format."""

    id: str
    title: str
    release_id: str
    edition: str
    capabilities: FormatCapabilities

    def detect(self, data: bytes) -> bool:
        """Return whether ``data`` belongs to this format."""

    def inspect(self, data: bytes, *, with_inventory: bool = True) -> SaveInfo:
        """Inspect bytes without modifying them."""

    def prepare(
        self,
        data: bytes,
        plan: EditPlan,
        *,
        source_name: str | None = None,
        catalog: ItemCatalog | None = None,
        game_catalog: GameCatalog | None = None,
    ) -> PreparedEdit:
        """Prepare an immutable edit for bytes in this format."""


@dataclass(frozen=True)
class DetectionFailure:
    """Why one registered format rejected a byte sequence."""

    format_id: str
    format_title: str
    reason: str


@dataclass(frozen=True)
class FormatInspection:
    """Inspection result plus the format metadata selected for its bytes."""

    format_id: str
    format_title: str
    info: SaveInfo
    release_id: str = ""
    edition: str = ""
    capabilities: FormatCapabilities = field(default_factory=FormatCapabilities)
    catalog: ItemCatalog | None = None
    game_catalog: GameCatalog | None = None
    # Names/icons only: may include a community mod the save was made with.
    display_catalog: ItemCatalog | None = None


class FormatDetectionError(SaveError):
    """A stable, user-facing error for bytes no registered format accepts."""

    def __init__(
        self,
        *,
        display_name: str,
        size: int,
        failures: tuple[DetectionFailure, ...],
        supported: tuple[SaveFormat, ...],
    ) -> None:
        self.display_name = display_name
        self.size = size
        self.failures = failures
        self.supported = supported
        reasons = "; ".join(
            f"{failure.format_id} ({failure.format_title}) — {failure.reason}"
            for failure in failures
        ) or "зарегистрированные форматы отсутствуют"
        supported_text = ", ".join(
            f"{format_.id} — {format_.title}" for format_ in supported
        ) or "нет зарегистрированных форматов"
        super().__init__(
            f"Error: Формат файла {display_name!r} не распознан "
            f"(размер: {size} байт). Причины: {reasons}. "
            f"Поддерживаются сейчас: {supported_text}."
        )


_PLAN_CAPABILITIES = (
    ("money", "edit_money"),
    ("stacks", "edit_stacks"),
    ("durability", "edit_durability"),
    ("detach", "remove_items"),
    ("moves", "move_items"),
    ("adds", "add_items"),
    ("upgrades", "edit_upgrades"),
    ("placements", "edit_placement"),
    ("faction_relations", "edit_relations"),
    ("player_faction", "edit_player_faction"),
)


def require_plan_capabilities(capabilities: FormatCapabilities, plan: EditPlan) -> None:
    """Refuse any plan field whose capability is not writable for the format.

    The UI hides such controls, but the CLI and other callers reach the
    writer directly; the gate must hold at the format boundary too.
    """

    for field_name, capability in _PLAN_CAPABILITIES:
        value = getattr(plan, field_name)
        if value is None or value == ():
            continue
        support = capabilities.support(capability)
        if not support.writable:
            reason = f": {support.reason}" if support.reason else ""
            raise SaveError(
                f"{capability} не подтверждён для этого формата "
                f"({support.maturity}){reason}"
            )
    if plan.raw or plan.attach:
        raise SaveError("raw/attach patches are research-only and never written")


_S2_RELEASE = release_by_id("stalker2")


class _Stalker2Format:
    id = _S2_RELEASE.id
    title = _S2_RELEASE.title
    release_id = _S2_RELEASE.id
    edition = _S2_RELEASE.edition
    capabilities = gate_mutations_for_release(
        release_id,
        FormatCapabilities(
            read_inventory=True,
            catalog=True,
            equipment=equipment_support_for_release(_S2_RELEASE.id),
            mutation_support={
                "edit_money": CapabilitySupport("experimental"),
                # L5 on 2026-09-26: consumable and ammo counts written through
                # Steam Auto-Cloud were accepted by the game (ED-3).
                "edit_stacks": CapabilitySupport("experimental"),
                "edit_durability": _S2_RELEASE.equipment.support("durability")
                if _S2_RELEASE.equipment is not None
                else CapabilitySupport("unsupported"),
            },
        ),
    )

    def __init__(self) -> None:
        # Catalog discovery can inspect Steam library metadata and loose cfg
        # trees.  The service asks for both the item catalog and the full game
        # catalog during one save inspection, so keep one source-scoped result
        # instead of parsing the same tree twice.  ``None`` sources are not
        # cached because an explicit Zone Kit/Workshop environment can change
        # during a process lifetime.
        self._catalog_cache: dict[
            tuple[str, tuple[str, ...]], tuple[ItemCatalog | None, GameCatalog | None]
        ] = {}

    def detect(self, data: bytes) -> bool:
        """Recognize the confirmed S.T.A.L.K.E.R. 2 container signature.

        Detection is deliberately defensive: arbitrary foreign bytes are an
        expected input to this method and must never escape parser exceptions.
        The existing parser's unique money anchor is the only confirmed
        content marker available to M01.
        """

        try:
            info = inspect_save(data, with_inventory=False)
        except Exception:
            return False
        return info.money_anchor_count == 1

    def detection_reason(self, data: bytes) -> str:
        try:
            info = inspect_save(data, with_inventory=False)
        except Exception as exc:
            return f"{type(exc).__name__}: {exc}"
        if info.money_anchor_count == 0:
            try:
                raw = decompress_save(data)
            except Exception:
                raw = b""
            if raw.count(WALLET_FIELD_ID) == 1:
                # Read-only diagnosis; nothing is parsed from this layout.
                return (
                    "legacy S2 layout: wallet field present without the confirmed "
                    "anchor (save from a launch build, re-save it in the game)"
                )
        return (
            "подтверждённая wallet anchor встречается "
            f"{info.money_anchor_count} раз(а), ожидалась ровно 1"
        )

    def inspect(self, data: bytes, *, with_inventory: bool = True) -> SaveInfo:
        return inspect_save(data, with_inventory=with_inventory)

    def catalog_for_source(
        self,
        source_name: str | None,
        *,
        catalog_roots: Sequence[Path] = (),
    ) -> ItemCatalog | None:
        """Read loose S2 metadata, keeping Workshop overlays explicit."""

        return self._catalog_bundle_for_source(source_name, catalog_roots=catalog_roots)[0]

    def _catalog_bundle_for_source(
        self,
        source_name: str | None,
        *,
        catalog_roots: Sequence[Path] = (),
    ) -> tuple[ItemCatalog | None, GameCatalog | None]:
        cache_key = (
            str(source_name) if source_name else "",
            tuple(str(Path(root).expanduser()) for root in catalog_roots),
        )
        if (cache_key[0] or cache_key[1]) and cache_key in self._catalog_cache:
            return self._catalog_cache[cache_key]

        provider = S2CatalogProvider()
        release = release_by_id(self.release_id)
        installed_roots: list[Path] = []
        steam_roots: tuple[Path, ...] = ()
        try:
            from .platforms import installed_releases, steam_libraries

            installed_roots.extend(
                game.install_dir
                for game in installed_releases()
                if game.release_id == self.release_id
            )
            steam_roots = steam_libraries()
        except (OSError, RuntimeError):
            pass
        sources = discover_s2_catalog_sources(
            source_name,
            installed_roots=installed_roots,
            steam_libraries=steam_roots,
            catalog_roots=catalog_roots,
        )
        result: tuple[ItemCatalog | None, GameCatalog | None]
        for source in sources:
            bundle = self._load_bundle_source(provider, release, source)
            if bundle is not None:
                result = (bundle.items, bundle)
                if cache_key[0] or cache_key[1]:
                    self._catalog_cache[cache_key] = result
                return result
        result = (None, None)
        if cache_key[0] or cache_key[1]:
            self._catalog_cache[cache_key] = result
        return result

    def game_catalog_for_source(
        self,
        source_name: str | None,
        *,
        catalog_roots: Sequence[Path] = (),
    ) -> GameCatalog | None:
        """Expose S2 item/upgrades metadata with no faction or writer claim."""
        return self._catalog_bundle_for_source(source_name, catalog_roots=catalog_roots)[1]

    @staticmethod
    def _load_bundle_source(
        provider: S2CatalogProvider,
        release: ReleaseDescriptor,
        source: S2CatalogSource,
    ) -> GameCatalog | None:
        if source.kind == "workshop":
            return provider.load_overlay_bundle(release, source.root)
        return provider.load_bundle(release, source.root)

    def prepare(
        self,
        data: bytes,
        plan: EditPlan,
        *,
        source_name: str | None = None,
        catalog: ItemCatalog | None = None,
        game_catalog: GameCatalog | None = None,
    ) -> PreparedEdit:
        require_plan_capabilities(self.capabilities, plan)
        return prepare_edit(data, plan)


class _XRayFormat:
    """Adapter exposing one original-game X-Ray family to the shared registry."""

    def __init__(self, spec: XRayFormatSpec) -> None:
        self.spec = spec
        self.id = spec.id
        self.title = spec.title
        self.release_id = spec.id
        release = release_by_id(spec.id)
        self.edition = release.edition
        equipment = release.equipment
        if equipment is None:
            raise ValueError(f"release {spec.id!r} lacks equipment metadata")
        self.capabilities = gate_mutations_for_release(
            self.release_id,
            FormatCapabilities(
                read_inventory=True,
                catalog=True,
                equipment=equipment_support_for_release(spec.id),
                mutation_support={
                    "edit_money": CapabilitySupport("verified"),
                    "edit_stacks": CapabilitySupport("verified"),
                    "add_items": CapabilitySupport("verified"),
                    "remove_items": CapabilitySupport("verified"),
                    "edit_durability": equipment.support("durability"),
                    "edit_relations": CapabilitySupport("experimental"),
                    "edit_player_faction": CapabilitySupport("experimental"),
                    "edit_placement": equipment.support("placement"),
                    **(
                        {"edit_upgrades": equipment.support("upgrades")}
                        if equipment.support("upgrades").writable
                        else {}
                    ),
                },
            ),
        )

    def detect(self, data: bytes) -> bool:
        # Avoid decompressing the same bytes for all three X-Ray adapters when
        # the outer version already selects a single family.
        if len(data) < 8:
            return False
        outer = struct.unpack_from("<I", data, 4)[0]
        if outer not in self.spec.outer_versions:
            return False
        try:
            parse_xray(data, self.spec, with_inventory=False)
        except Exception:
            return False
        return True

    def detect_fast(self, data: bytes) -> bool:
        """Recognize a candidate without scanning the registry tail.

        Slot discovery uses this inexpensive probe outside the UI thread.  A
        selected row still goes through ``detect``/full inspection before any
        edit is prepared.
        """

        if len(data) < 8:
            return False
        outer = struct.unpack_from("<I", data, 4)[0]
        if outer not in self.spec.outer_versions:
            return False
        try:
            parse_xray(
                data,
                self.spec,
                with_inventory=False,
                strict_registry=False,
            )
        except Exception:
            return False
        return True

    def detection_reason(self, data: bytes) -> str:
        if len(data) < 8:
            return "заголовок короче 8 байт"
        outer = struct.unpack_from("<I", data, 4)[0]
        if outer not in self.spec.outer_versions:
            expected = ", ".join(str(value) for value in sorted(self.spec.outer_versions))
            return f"outer version={outer}, для {self.id} ожидалось {expected}"
        try:
            parsed = parse_xray(data, self.spec, with_inventory=False)
        except Exception as exc:
            return f"{type(exc).__name__}: {exc}"
        return f"X-Ray actor spawn version {parsed.actor_version} подтверждён"

    def inspect(self, data: bytes, *, with_inventory: bool = True) -> SaveInfo:
        return inspect_xray(data, self.spec, with_inventory=with_inventory)

    def catalog_for_source(
        self,
        source_name: str | None,
        *,
        catalog_roots: Sequence[Path] = (),
    ) -> ItemCatalog | None:
        """Find an official catalog by walking up from a local save path."""

        if not source_name:
            return None
        source = Path(source_name).expanduser()
        if not source.is_absolute() and not source.exists():
            return None
        try:
            source = source.resolve()
        except OSError:
            return None
        start = source.parent if source.is_file() else source
        provider = XRayCatalogProvider()
        release = release_by_id(self.release_id)
        for root in (start, *start.parents):
            catalog = provider.load(release, root)
            if catalog is not None:
                return catalog
        # The repository ships a compact snapshot generated from official
        # resources.  It is a metadata-only fallback for releases whose
        # installation has no unpacked/verified catalog (notably the local
        # Linux SoC install); it never supplies prototypes or save bytes.
        generated = provider.load_generated_bundle(release)
        return generated.items if generated is not None else None

    def display_catalog_for_source(self, source_name: str | None) -> ItemCatalog | None:
        """Names and icons from a modded install next to the save, if any.

        Presentation only: the modded tree is never used to prepare an edit.
        Its definitions come first; official ones fill the gaps.
        """

        if not source_name:
            return None
        try:
            start = Path(source_name).expanduser().resolve()
        except OSError:
            return None
        start = start.parent if start.is_file() else start
        for root in (start, *start.parents):
            if has_mod_overlay(root):
                return _mod_display_catalog(self.release_id, str(root))
        return None

    def game_catalog_for_source(
        self,
        source_name: str | None,
        *,
        catalog_roots: Sequence[Path] = (),
    ) -> GameCatalog | None:
        """Find the full official item/community catalog for a local save."""

        if not source_name:
            return None
        source = Path(source_name).expanduser()
        if not source.is_absolute() and not source.exists():
            return None
        try:
            source = source.resolve()
        except OSError:
            return None
        start = source.parent if source.is_file() else source
        provider = XRayCatalogProvider()
        release = release_by_id(self.release_id)
        for root in (start, *start.parents):
            catalog = provider.load_bundle(release, root)
            if catalog is not None:
                return catalog
        generated = provider.load_generated_bundle(release)
        return generated

    def prepare(
        self,
        data: bytes,
        plan: EditPlan,
        *,
        source_name: str | None = None,
        catalog: ItemCatalog | None = None,
        game_catalog: GameCatalog | None = None,
    ) -> PreparedEdit:
        require_plan_capabilities(self.capabilities, plan)
        selected_catalog = catalog or self.catalog_for_source(source_name)
        return prepare_xray(
            data,
            plan,
            self.spec,
            catalog=selected_catalog,
            faction_catalog=game_catalog.factions if game_catalog is not None else None,
            upgrade_catalog=game_catalog.upgrades if game_catalog is not None else None,
        )


STALKER2_FORMAT: SaveFormat = _Stalker2Format()
STALKER_SOC_FORMAT: SaveFormat = _XRayFormat(SOC_FORMAT)
STALKER_CS_FORMAT: SaveFormat = _XRayFormat(CS_FORMAT)
STALKER_COP_FORMAT: SaveFormat = _XRayFormat(COP_FORMAT)
_REGISTERED_FORMATS: list[SaveFormat] = []


def register(fmt: SaveFormat) -> None:
    """Register one static format, rejecting duplicate identifiers."""

    if any(existing.id == fmt.id for existing in _REGISTERED_FORMATS):
        raise ValueError(f"Format ID already registered: {fmt.id!r}")
    _REGISTERED_FORMATS.append(fmt)


def formats() -> tuple[SaveFormat, ...]:
    """Return the registered formats in deterministic registration order."""

    return tuple(_REGISTERED_FORMATS)


def by_id(format_id: str) -> SaveFormat:
    """Return a format by ID or raise ``KeyError`` for an unknown ID."""

    for fmt in _REGISTERED_FORMATS:
        if fmt.id == format_id:
            return fmt
    raise KeyError(format_id)


def detect(data: bytes) -> SaveFormat | None:
    """Return the first format accepting ``data``, or ``None``."""

    for fmt in _REGISTERED_FORMATS:
        try:
            if fmt.detect(data):
                return fmt
        except Exception:
            # A foreign or malformed file must not prevent other registered
            # formats from getting a chance to inspect its bytes.
            continue
    return None


def detect_fast(data: bytes) -> SaveFormat | None:
    """Return a format using its optional cheap candidate detector.

    This is for local slot discovery only.  Callers that need an inspection
    result or an edit must use :func:`detect` and the normal strict parser.
    """

    for fmt in _REGISTERED_FORMATS:
        fast_detector = getattr(fmt, "detect_fast", None)
        try:
            accepted = (
                fast_detector(data)
                if callable(fast_detector)
                else fmt.detect(data)
            )
        except Exception:
            continue
        if accepted:
            return fmt
    return None


def detection_failures(data: bytes) -> tuple[DetectionFailure, ...]:
    """Return per-format reasons without letting malformed input escape."""

    failures: list[DetectionFailure] = []
    for fmt in _REGISTERED_FORMATS:
        try:
            if fmt.detect(data):
                return ()
        except Exception as exc:
            reason = f"{type(exc).__name__}: {exc}"
        else:
            reason_fn = getattr(fmt, "detection_reason", None)
            if callable(reason_fn):
                try:
                    reason = str(reason_fn(data))
                except Exception as exc:
                    reason = f"{type(exc).__name__}: {exc}"
            else:
                reason = "сигнатура не подтверждена"
        failures.append(DetectionFailure(fmt.id, fmt.title, reason))
    return tuple(failures)


def format_detection_error(
    data: bytes, *, display_name: str | None = None
) -> FormatDetectionError:
    """Build the shared diagnostic raised for an unknown save format."""

    label = display_name.strip() if display_name and display_name.strip() else "<без имени>"
    return FormatDetectionError(
        display_name=label,
        size=len(data),
        failures=detection_failures(data),
        supported=formats(),
    )


def detect_or_raise(data: bytes, *, display_name: str | None = None) -> SaveFormat:
    """Resolve a format or raise the shared, user-facing diagnostic."""

    format_ = detect(data)
    if format_ is None:
        raise format_detection_error(data, display_name=display_name)
    return format_


register(STALKER2_FORMAT)
register(STALKER_SOC_FORMAT)
register(STALKER_CS_FORMAT)
register(STALKER_COP_FORMAT)


__all__ = [
