from __future__ import annotations

import hashlib

from save_format import SaveError, patch_save

from .models import EditPlan, PreparedEdit


def _sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def prepare_edit(data: bytes, plan: EditPlan) -> PreparedEdit:
    """Apply one immutable plan after checking the analyzed source identity.

    Length-changing inventory operations and raw offsets cannot be safely
    combined.  The rejection happens before ``patch_save`` so callers cannot
    accidentally produce a partially transformed payload.
    """

    actual_sha = _sha256(data)
    if actual_sha != plan.source.sha256:
        raise SaveError(
            "Источник изменился после анализа: "
            f"SHA256 expected={plan.source.sha256} actual={actual_sha}"
        )

    if plan.raw and (plan.detach or plan.attach):
        raise SaveError(
            "Нельзя совмещать raw patch с detach/attach в одном edit plan"
        )
    if plan.adds:
        raise SaveError(
            "Добавление предметов не подтверждено для S.T.A.L.K.E.R. 2"
        )
    if plan.upgrades:
        raise SaveError(
            "Изменение улучшений не подтверждено для S.T.A.L.K.E.R. 2"
        )

    result = patch_save(
        data,
        new_money=plan.money,
        stack_counts=dict(plan.stacks),
        moves={handle: (x, y) for handle, x, y in plan.moves},
        detach=dict(plan.detach),
        attach_orphans={
            handle: (x, y, width, height)
            for handle, x, y, width, height in plan.attach
        },
        raw_patches=plan.raw,
        durability=dict(plan.durability),
    )
    output = bytes(result.data)
    return PreparedEdit(plan=plan, data=output, output_sha256=_sha256(output))

files.editor/s2_catalog.py:
"""Read-only metadata catalog for loose S.T.A.L.K.E.R. 2 resources.

S.T.A.L.K.E.R. 2 keeps its gameplay prototypes in Unreal-style ``.cfg``
structures.  The canonical path consumes only loose files under the official
``Content/GameLite/GameData`` tree.  An explicitly selected Zone Kit or
Workshop tree can be read as provenance-labeled catalog research data, but
the reader does not unpack PAK files or claim that an Unreal prototype SID is
the compact key stored in a save.  The latter mapping and every S2 save writer
remain separate evidence gates.
"""

from __future__ import annotations

import json
import os
import re
from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass, field
from pathlib import Path
from typing import Literal

from .catalog import (
    FactionCatalog,
    GameCatalog,
    ItemCatalog,
    ItemDefinition,
    UpgradeCatalog,
    UpgradeDefinition,
)
from .releases import ReleaseDescriptor, release_by_id

_MOD_PARTS = frozenset(
    {
        "~mods",
        "mods",
        "savedmods",
        "pak__mods",
        "s2zonamods",
        "anomaly",
        "misery",
        "ogsm",
    }
)
_ITEM_FIELDS = frozenset(
    {
        "type",
        "itemtype",
        "itemslottype",
        "weight",
        "maxstackcount",
        "maxstack",
        "displayname",
        "display_name",
        "icon",
        "iconpath",
        "icontexture",
        "inventoryicon",
    }
)
_CATEGORY_BY_FILE = {
    "ammo": "ammo",
    "armor": "outfit",
    "artifact": "artifact",
    "attach": "attachment",
    "consumable": "consumable",
    "detector": "detector",
    "grenade": "grenade",
    "keyitem": "quest",
    "questitem": "quest",
    "weapon": "weapon",
}
_UPGRADE_KEY_RE = re.compile(r"upgrade.*sids?$", re.IGNORECASE)
_REFKEY_RE = re.compile(r"\brefkey\s*=\s*([^;}]+)", re.IGNORECASE)
_NUMBER_RE = re.compile(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?")
_S2_APP_ID = release_by_id("stalker2").app_id
_ZONE_KIT_ENV_KEYS = ("STALKER2_ZONE_KIT_ROOT", "ZONE_KIT_ROOT")
_WORKSHOP_ENV_KEYS = ("STALKER2_WORKSHOP_ROOT",)
_LOCALIZATION_FILE_LIMIT = 256
_LOCALIZATION_FILE_BYTES = 16 * 1024 * 1024


class S2CatalogError(ValueError):
    """A malformed loose S2 config file."""


@dataclass(frozen=True)
class S2CatalogSource:
    """One explicitly discoverable loose metadata source.

    ``official`` and ``zonekit`` sources are read through the canonical
    parser.  ``workshop`` is deliberately a separate opt-in source because a
    mod overlay can override the game's prototypes and must never silently
    become authoritative save metadata.
    """

    root: Path
    kind: Literal["official", "zonekit", "workshop"]

    def __post_init__(self) -> None:
        root = Path(self.root).expanduser()
        object.__setattr__(self, "root", root)
        if self.kind not in {"official", "zonekit", "workshop"}:
            raise ValueError(f"unsupported S2 catalog source kind: {self.kind!r}")


@dataclass
class _S2Record:
    name: str
    source: str
    refkey: str | None = None
    values: dict[str, list[str]] = field(default_factory=dict)

    def add(self, key: str, value: str, context: tuple[str, ...] = ()) -> None:
        path = (*context, key) if context else (key,)
        self.values.setdefault("::".join(path).casefold(), []).append(value)


@dataclass
class _UpgradeRow:
    category: str | None
    source: str
    display_name: str | None = None
    items: set[str] = field(default_factory=set)


def _strip_comment(line: str) -> str:
    quote: str | None = None
    index = 0
    while index < len(line):
        character = line[index]
        if character in "\"'":
            if quote == character:
                quote = None
            elif quote is None:
                quote = character
        elif quote is None:
            if character == ";":
                return line[:index]
            if character == "/" and index + 1 < len(line) and line[index + 1] == "/":
                return line[:index]
        index += 1
    return line


def _begin_name(line: str) -> str:
    left = line.split(":", 1)[0].strip()
    return left if left and left.casefold() != "struct.begin" else ""


def _begin_refkey(line: str) -> str | None:
    match = _REFKEY_RE.search(line)
    if match is None:
        return None
    value = match.group(1).strip().strip("\"'")
    return value or None


def _parse_cfg(text: str, source: str) -> tuple[_S2Record, ...]:
    records: list[_S2Record] = []
    active: _S2Record | None = None
    contexts: list[str] = []
    depth = 0
    for line_number, raw_line in enumerate(text.splitlines(), 1):
        line = _strip_comment(raw_line).strip()
        if not line or line.startswith("#"):
            continue
        lowered = line.casefold()
        if "struct.begin" in lowered:
            if depth == 0:
                active = _S2Record(
                    name=_begin_name(line),
                    source=source,
                    refkey=_begin_refkey(line),
                )
                records.append(active)
            contexts.append(_begin_name(line))
            depth += 1
            continue
        if lowered.startswith("struct.end"):
            if depth == 0:
                raise S2CatalogError(f"{source}:{line_number}: лишний struct.end")
            depth -= 1
            if contexts:
                contexts.pop()
            if depth == 0:
                active = None
            continue
        if active is None or depth == 0 or "=" not in line:
            continue
        key, value = line.split("=", 1)
        key = key.strip()
        value = value.strip().strip("\"'").strip()
        if key and value:
            active.add(key, value, tuple(contexts[1:]))

    if depth != 0:
        raise S2CatalogError(f"{source}: незакрытый struct.begin")
    return tuple(records)


def _read_text(path: Path) -> str:
    data = path.read_bytes()
    for encoding in ("utf-8-sig", "utf-8", "cp1252"):
        try:
            return data.decode(encoding)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", errors="replace")


def _localization_roots(root: Path) -> tuple[Path, ...]:
    """Return bounded, conventional Zone Kit localization directories."""

    candidates = (
        root / "Content" / "Localization",
        root / "Content" / "LocalizationDB",
        root / "Content" / "GameLite" / "Localization",
        root / "Localization",
        root / "LocalizationDB",
        root / "LocalizationStrings",
        root / "Stalker2" / "Content" / "Localization",
    )
    result: list[Path] = []
    seen: set[Path] = set()
    for candidate in candidates:
        try:
            resolved = candidate.resolve()
        except OSError:
            resolved = candidate
        if resolved in seen or not resolved.is_dir():
            continue
        seen.add(resolved)
        result.append(resolved)
    return tuple(result)


def _localization_value(value: object) -> str | None:
    if not isinstance(value, str):
        return None
    text = value.strip().strip("\"'")
    return text or None


def _collect_localization(
    value: object,
    result: dict[str, str],
    inherited_key: str | None = None,
) -> None:
    """Collect common Zone Kit JSON localization export shapes."""

    if isinstance(value, str):
        text = _localization_value(value)
        if inherited_key and text is not None:
            result.setdefault(inherited_key, text)
        return
    if isinstance(value, Mapping):
        key = inherited_key
        for candidate in ("id", "key", "sid", "name", "loc_key", "localization_key"):
            candidate_value = _localization_value(value.get(candidate))
            if candidate_value:
                key = candidate_value
                break
        for candidate in ("text", "Text", "value", "Value", "translation", "Translation"):
            text = _localization_value(value.get(candidate))
            if key and text is not None:
                result.setdefault(key, text)
                break
        for raw_key, child in value.items():
            if not isinstance(raw_key, str):
                continue
            if raw_key.casefold() in {
                "id",
                "key",
                "sid",
                "name",
                "loc_key",
                "localization_key",
                "text",
                "value",
                "translation",
            }:
                continue
            if isinstance(child, str):
                text = _localization_value(child)
                if text is not None:
                    result.setdefault(raw_key.strip(), text)
            else:
                _collect_localization(child, result, raw_key.strip())
        return
    if isinstance(value, list):
        for child in value:
            _collect_localization(child, result, inherited_key)


def _load_localization(root: Path) -> dict[str, str]:
    """Load safe JSON localization exports without scanning arbitrary assets."""

    files: list[Path] = []
    for directory in _localization_roots(root):
        try:
            files.extend(
                path
                for path in directory.rglob("*.json")
                if path.is_file() and not path.is_symlink()
            )
        except OSError:
            continue
    files = sorted(
        set(files),
        key=lambda path: (
            0 if any(part.casefold() in {"en", "en-us", "english"} for part in path.parts) else 1,
            path.as_posix().casefold(),
        ),
    )[:_LOCALIZATION_FILE_LIMIT]
    result: dict[str, str] = {}
    for path in files:
        try:
            if path.stat().st_size > _LOCALIZATION_FILE_BYTES:
                continue
            payload = json.loads(path.read_text(encoding="utf-8-sig"))
        except (OSError, UnicodeError, json.JSONDecodeError):
            continue
        _collect_localization(payload, result)
    return result


def _is_mod_path(path: Path) -> bool:
    return any(part.casefold() in _MOD_PARTS for part in path.parts)


def _resolved_path(value: str | Path) -> Path:
    path = Path(value).expanduser()
    try:
        return path.resolve()
    except OSError:
        return path


def _environment_paths(
    environ: Mapping[str, str],
    keys: Sequence[str],
) -> tuple[Path, ...]:
    paths: list[Path] = []
    for key in keys:
        raw = environ.get(key, "")
        for value in raw.split(os.pathsep):
            if value.strip():
                paths.append(_resolved_path(value.strip()))
    return tuple(paths)


def _append_source(
    sources: list[S2CatalogSource],
    seen: set[tuple[Path, str]],
    root: str | Path,
    kind: Literal["official", "zonekit", "workshop"],
) -> None:
    path = _resolved_path(root)
    try:
        if not path.is_dir():
            return
    except OSError:
        return
    key = (path, kind)
    if key in seen:
        return
    seen.add(key)
    sources.append(S2CatalogSource(path, kind))


def _explicit_source_kind(root: str | Path) -> Literal["zonekit", "workshop"]:
    path = _resolved_path(root)
    parts = tuple(part.casefold() for part in path.parts)
    if "workshop" in parts and str(_S2_APP_ID) in parts:
        return "workshop"
    if path.name.isdigit() and path.parent.name == str(_S2_APP_ID):
        return "workshop"
    return "zonekit"


def _workshop_item_roots(root: str | Path) -> tuple[Path, ...]:
    """Return Steam Workshop item directories below one library override."""

    path = _resolved_path(root)
    if not path.is_dir():
        return ()
    if (path / "Content").is_dir() or (path / "Stalker2").is_dir():
        return (path,)
    library_content_root = path / "steamapps" / "workshop" / "content" / str(_S2_APP_ID)
    if library_content_root.is_dir():
        content_root = library_content_root
    elif path.name == str(_S2_APP_ID):
        content_root = path
    elif (path / str(_S2_APP_ID)).is_dir():
        content_root = path / str(_S2_APP_ID)
    elif path.name.isdigit() and path.parent.name == str(_S2_APP_ID):
        return (path,)
    else:
        content_root = path
    try:
        return tuple(
            child
            for child in sorted(content_root.iterdir(), key=lambda item: item.name.casefold())
            if child.is_dir() and not child.is_symlink()
        )
    except OSError:
        return ()


def discover_s2_catalog_sources(
    source_name: str | None = None,
    *,
    installed_roots: Iterable[str | Path] = (),
    steam_libraries: Iterable[str | Path] = (),
    catalog_roots: Iterable[str | Path] = (),
    environ: Mapping[str, str] | None = None,
) -> tuple[S2CatalogSource, ...]:
    """Discover loose S2 metadata without treating mods as canonical.

    Explicit catalog roots are searched first.  The source path and installed
    roots follow. Zone Kit roots are explicit environment overrides. Steam Workshop directories are
    included last and are only usable through :meth:`load_overlay`, so an
    overlay cannot shadow an official catalog by accident.
    """

    sources: list[S2CatalogSource] = []
    seen: set[tuple[Path, str]] = set()
    for catalog_root in catalog_roots:
        _append_source(sources, seen, catalog_root, _explicit_source_kind(catalog_root))
    if source_name:
        source_path = Path(source_name).expanduser()
        if source_path.is_absolute() or source_path.exists():
            try:
                source_path = source_path.resolve()
            except OSError:
                pass
            start = source_path.parent if source_path.is_file() else source_path
            for source_root in (start, *start.parents):
                _append_source(sources, seen, source_root, "official")

    for installed_root in installed_roots:
        _append_source(sources, seen, installed_root, "official")

    env = os.environ if environ is None else environ
    for zonekit_root in _environment_paths(env, _ZONE_KIT_ENV_KEYS):
        _append_source(sources, seen, zonekit_root, "zonekit")

    workshop_roots = list(_environment_paths(env, _WORKSHOP_ENV_KEYS))
    workshop_roots.extend(_resolved_path(library) for library in steam_libraries)
    for root in workshop_roots:
        for item_root in _workshop_item_roots(root):
            _append_source(sources, seen, item_root, "workshop")
    return tuple(sources)


def _effective_values(
    record: _S2Record,
    by_reference: dict[str, _S2Record],
    cache: dict[int, dict[str, tuple[str, ...]]],
    stack: tuple[int, ...] = (),
) -> dict[str, tuple[str, ...]]:
    identity = id(record)
    if identity in cache:
        return cache[identity]
    if identity in stack:
        return {}
    values: dict[str, tuple[str, ...]] = {}
    if record.refkey:
        base = by_reference.get(record.refkey.casefold())
        if base is not None:
            values.update(_effective_values(base, by_reference, cache, (*stack, identity)))
    values.update({key: tuple(items) for key, items in record.values.items()})
    cache[identity] = values
    return values


def _first(values: dict[str, tuple[str, ...]], *keys: str) -> str | None:
    for key in keys:
        entries = values.get(key.casefold())
        if entries:
            return entries[0]
    wanted = {key.casefold() for key in keys}
    for path, entries in values.items():
        if path.rsplit("::", 1)[-1] in wanted and entries:
            return entries[0]
    return None


def _record_first(record: _S2Record, key: str) -> str | None:
    entries = record.values.get(key.casefold())
    return entries[0] if entries else None


def _number(value: str | None) -> float | None:
    if value is None:
        return None
    match = _NUMBER_RE.search(value)
    if match is None:
        return None
    try:
        return float(match.group(0))
    except ValueError:
        return None


def _integer(value: str | None) -> int | None:
    number = _number(value)
    if number is None or not number.is_integer() or number < 0:
        return None
    return int(number)


def _enum_leaf(value: str) -> str | None:
    value = value.strip().strip("\"'")
    if "::" in value:
        value = value.rsplit("::", 1)[-1]
    value = value.strip()
    return None if value.casefold() in {"", "none", "null"} else value


def _slots(values: dict[str, tuple[str, ...]]) -> tuple[str, ...]:
    result: list[str] = []
    for key in ("itemslottype", "itemslottypes"):
        for value in (
            entry
            for path, entries in values.items()
            if path.rsplit("::", 1)[-1] == key
            for entry in entries
        ):
            for token in re.split(r"[,;]", value):
                item = _enum_leaf(token)
                if item is not None and item not in result:
                    result.append(item)
    return tuple(result)


def _category(record: _S2Record, values: dict[str, tuple[str, ...]]) -> str | None:
    type_value = _first(values, "type", "itemtype", "prototypeclass")
    lowered = (type_value or "").casefold()
    for token, category in (
        ("weapon", "weapon"),
        ("armor", "outfit"),
        ("outfit", "outfit"),
        ("artifact", "artifact"),
        ("ammo", "ammo"),
        ("consum", "consumable"),
        ("grenade", "grenade"),
        ("detector", "detector"),
        ("attach", "attachment"),
        ("quest", "quest"),
        ("keyitem", "quest"),
    ):
        if token in lowered:
            return category
    filename = record.source.rsplit("/", 1)[-1].casefold()
    for token, category in _CATEGORY_BY_FILE.items():
        if token in filename:
            return category
    return "item"


def _is_item(record: _S2Record, values: dict[str, tuple[str, ...]]) -> bool:
    leaves = {path.rsplit("::", 1)[-1] for path in values}
    # SID is the record identity, not an arbitrary nested metadata field.
    # Requiring the top-level key prevents a nested attachment/property SID
    # from becoming a selectable item definition by accident.
    return bool(record.values.get("sid")) and bool(_ITEM_FIELDS & leaves)


def _display_name_key(values: dict[str, tuple[str, ...]]) -> str | None:
    value = _first(
        values,
        "displayname",
        "display_name",
        "localizedname",
        "itemname",
    )
    if value is None:
        return None
    normalized = value.strip().strip("\"'")
    return normalized or None


def _display_name(
    values: dict[str, tuple[str, ...]],
    localization: Mapping[str, str] | None = None,
) -> str | None:
    key = _display_name_key(values)
    if key is None:
        return None
    if localization:
        translated = localization.get(key)
        if translated is None:
            folded = key.casefold()
            translated = next(
                (value for candidate, value in localization.items() if candidate.casefold() == folded),
                None,
            )
        if translated:
            return translated
    return key


def _icon_texture(values: dict[str, tuple[str, ...]]) -> str | None:
    value = _first(
        values,
        "icon",
        "iconpath",
        "icontexture",
        "inventoryicon",
        "itemicon",
    )
    if value is None:
        return None
    normalized = value.strip().strip("\"'")
    return normalized or None


def _tokens(value: str) -> tuple[str, ...]:
    return tuple(
        token
        for token in re.findall(r"[A-Za-z0-9_./-]+", value)
        if token.casefold() not in {"none", "null", "empty"}
    )


def _sids(values: dict[str, tuple[str, ...]]) -> tuple[str, ...]:
    result: list[str] = []
    for key, entries in values.items():
        path_parts = key.split("::")
        if not any(_UPGRADE_KEY_RE.fullmatch(part) for part in path_parts):
            continue
        for entry in entries:
            for token in _tokens(entry):
                if token in result:
                    continue
                result.append(token)
    return tuple(result)


def _item_sids(values: dict[str, tuple[str, ...]]) -> tuple[str, ...]:
    result: list[str] = []
    for key, entries in values.items():
        leaf = key.rsplit("::", 1)[-1]
        if leaf not in {"itemprototypesid", "itemprototypesids"}:
            continue
        for entry in entries:
            for token in _tokens(entry):
                if token not in result:
                    result.append(token)
    return tuple(result)


def _source(root: Path, path: Path) -> str:
    try:
        return path.relative_to(root).as_posix()
    except ValueError:
        return path.as_posix()


def _find_game_data(root: Path, *, allow_mod_path: bool = False) -> Path | None:
    candidates: list[Path] = [
        root / "Content" / "GameLite" / "GameData",
        root / "GameLite" / "GameData",
        root / "GameData",
        root / "Stalker2" / "Content" / "GameLite" / "GameData",
        root / "stalker2" / "Content" / "GameLite" / "GameData",
    ]
    if root.name.casefold() == "gamedata":
        candidates.insert(0, root)
    for candidate in candidates:
        if candidate.is_dir() and (allow_mod_path or not _is_mod_path(candidate)):
            return candidate
    if not allow_mod_path:
        return None
    try:
        nested_candidates = sorted(
            (
                path
                for path in root.rglob("GameData")
                if path.is_dir()
                and not path.is_symlink()
                and tuple(part.casefold() for part in path.parts[-3:])
                == ("content", "gamelite", "gamedata")
            ),
            key=lambda item: item.as_posix().casefold(),
        )
    except OSError:
        return None
    if nested_candidates:
        return nested_candidates[0]
    return None


def _catalog_source_root(root: Path, game_data: Path) -> Path:
    """Return the content root from which loose image assets are addressable."""

    lowered_parts = tuple(part.casefold() for part in game_data.parts)
    content_indexes = [
        index for index, part in enumerate(lowered_parts) if part == "content"
    ]
    try:
        content_index = content_indexes[-1]
    except IndexError:
        return root
    if content_index > 0:
        return Path(*game_data.parts[:content_index])
    if content_index == 0:
        return root.parent if root.name.casefold() == "content" else Path(game_data.anchor or "/")
    return root


class S2CatalogProvider:
    """Load loose S2 prototype metadata without save semantics."""

    def __init__(self) -> None:
        self._catalog: ItemCatalog | None = None
        self._game_catalog: GameCatalog | None = None

    def load(
        self,
        release: ReleaseDescriptor,
        game_root: Path | None = None,
    ) -> ItemCatalog | None:
        """Load canonical official metadata and reject mod overlays."""

        return self._load(release, game_root, allow_mod_overlay=False)

    def load_overlay(
        self,
        release: ReleaseDescriptor,
        game_root: Path | None = None,
    ) -> ItemCatalog | None:
        """Load one explicitly selected loose Workshop/mod metadata tree.

        This is catalog-only research data. It never changes the selected
        save format capabilities and it is never merged into an official
        catalog implicitly.
        """

        return self._load(release, game_root, allow_mod_overlay=True)

    def _load(
        self,
        release: ReleaseDescriptor,
        game_root: Path | None,
        *,
        allow_mod_overlay: bool,
    ) -> ItemCatalog | None:
        self._catalog = None
        self._game_catalog = None
        if release.family != "stalker2" or release.edition != "s2" or game_root is None:
            return None
        root = Path(game_root).expanduser()
        if not root.is_dir() or (not allow_mod_overlay and _is_mod_path(root)):
            return None
        game_data = _find_game_data(root, allow_mod_path=allow_mod_overlay)
        if game_data is None:
            return None
        item_root = game_data / "ItemPrototypes"
        if not item_root.is_dir() or (
            not allow_mod_overlay and _is_mod_path(item_root)
        ):
            return None
        # A Steam Workshop item can wrap the actual mod below
        # ``Stalker2/Mods/<name>/Content``.  Resolve the nearest Content root
        # before looking for localization so the outer Workshop container does
        # not hide the mod's human-readable names.
        localization = _load_localization(_catalog_source_root(root, game_data))

        item_paths = tuple(
            path
            for path in sorted(item_root.rglob("*.cfg"), key=lambda item: item.as_posix().casefold())
            if path.is_file()
            and not path.is_symlink()
            and (allow_mod_overlay or not _is_mod_path(path))
        )
        records: list[_S2Record] = []
        for path in item_paths:
            try:
                records.extend(_parse_cfg(_read_text(path), _source(root, path)))
            except (OSError, S2CatalogError):
                continue
        if not records:
            return None

        upgrade_paths = tuple(
            path
            for path in sorted(game_data.rglob("*.cfg"), key=lambda item: item.as_posix().casefold())
            if path.is_file()
            and not path.is_symlink()
            and (allow_mod_overlay or not _is_mod_path(path))
            and "upgrade" in path.as_posix().casefold()
            and path not in item_paths
        )
        upgrade_records_by_path: list[tuple[Path, tuple[_S2Record, ...]]] = []
        for path in upgrade_paths:
            try:
                parsed = _parse_cfg(_read_text(path), _source(root, path))
            except (OSError, S2CatalogError):
                continue
            if parsed:
                upgrade_records_by_path.append((path, parsed))

        by_reference: dict[str, _S2Record] = {}
        for record in (*records, *(record for _, parsed in upgrade_records_by_path for record in parsed)):
            by_reference.setdefault(record.name.casefold(), record)
            sid = _record_first(record, "sid")
            if sid:
                by_reference.setdefault(sid.casefold(), record)
        cache: dict[int, dict[str, tuple[str, ...]]] = {}
        items: list[ItemDefinition] = []
        item_by_sid: dict[str, ItemDefinition] = {}
        item_upgrade_refs: dict[str, set[str]] = {}
        for record in records:
            values = _effective_values(record, by_reference, cache)
            sid = _first(values, "sid")
            if sid is None or not _is_item(record, values) or sid in item_by_sid:
                continue
            definition = ItemDefinition(
                key=sid,
                display_name=_display_name(values, localization),
                category=_category(record, values),
                unit_weight=_number(_first(values, "weight")),
                width=None,
                height=None,
                max_stack=_integer(_first(values, "maxstackcount", "maxstack")),
                slots=_slots(values),
                prototype=None,
                source=f"{record.source}#{record.name or sid}",
                serialization_family=None,
                icon_texture=_icon_texture(values),
                display_name_key=_display_name_key(values),
            )
            items.append(definition)
            item_by_sid[sid] = definition
            item_upgrade_refs[sid] = set(_sids(values))
        if not items:
            return None

        source_root = _catalog_source_root(root, game_data)
        item_catalog = ItemCatalog(release.id, source_root, tuple(items))
        upgrade_rows: dict[str, _UpgradeRow] = {}
        for item_sid, upgrade_sids in item_upgrade_refs.items():
            for upgrade_sid in upgrade_sids:
                row = upgrade_rows.setdefault(
                    upgrade_sid,
                    _UpgradeRow(
                        category=item_by_sid[item_sid].category,
                        source=item_by_sid[item_sid].source,
                    ),
                )
                row.items.add(item_sid)

        for _, upgrade_records in upgrade_records_by_path:
            for record in upgrade_records:
                values = _effective_values(record, by_reference, cache)
                sid = _first(values, "sid")
                if sid is None:
                    continue
                row = upgrade_rows.setdefault(
                    sid,
                    _UpgradeRow(
                        category=_category(record, values),
                        source=f"{record.source}#{record.name or sid}",
                        display_name=_display_name(values, localization),
                    ),
                )
                if row.display_name is None:
                    row.display_name = _display_name(values, localization)
                for item_sid in _item_sids(values):
                    if item_sid in item_by_sid:
                        row.items.add(item_sid)

        upgrades = (
            UpgradeCatalog(
                release.id,
                source_root,
                tuple(
                    UpgradeDefinition(
                        key=key,
                        display_name=row.display_name,
                        category=row.category,
                        item_key=(
                            sorted(row.items)[0]
                            if row.items
                            else None
                        ),
                        source=row.source,
                        release_id=release.id,
                        applicable_item_keys=tuple(sorted(row.items)),
                    )
                    for key, row in sorted(upgrade_rows.items(), key=lambda item: item[0].casefold())
                ),
            )
            if upgrade_rows
            else None
        )
        empty_factions = FactionCatalog(release.id, source_root, ())
        self._catalog = item_catalog
        self._game_catalog = GameCatalog(release.id, item_catalog, empty_factions, upgrades)
        return item_catalog

    def load_bundle(
        self,
        release: ReleaseDescriptor,
        game_root: Path | None = None,
    ) -> GameCatalog | None:
        """Load item/upgrade metadata with an intentionally empty faction catalog."""

        self.load(release, game_root)
        return self._game_catalog

    def load_overlay_bundle(
        self,
        release: ReleaseDescriptor,
        game_root: Path | None = None,
    ) -> GameCatalog | None:
        """Load one explicit Workshop/mod tree as a catalog-only bundle."""

        self.load_overlay(release, game_root)
        return self._game_catalog

    def resolve(self, key: str) -> ItemDefinition | None:
        return self._catalog.resolve(key) if self._catalog is not None else None


__all__ = [
    "S2CatalogError",
    "S2CatalogProvider",
    "S2CatalogSource",
    "discover_s2_catalog_sources",
]

files.editor/xray_container.py:
"""The shared, game-independent part of an original X-Ray save.

The original trilogy stores a little-endian header followed by a raw LZO1X-1
stream.  This module deliberately stops at the container boundary: object
fields and game-specific versions belong to the later format readers.  The
compressor is a small literal-only encoder written from the public format
description.  It is sufficient for safe fixed-size payload edits.  Desktop
systems may use an optional system ``liblzo2`` decoder for large files; the
bounded Python decoder remains the portable and browser implementation.
"""

from __future__ import annotations

import struct
from dataclasses import dataclass
from typing import Any

from save_format import SaveError

try:
    import ctypes
    import ctypes.util
except ImportError:  # pragma: no cover - depends on the Python runtime
    _NATIVE_LZO: Any = None
else:
    _NATIVE_LZO = None
    try:
        _library_name = ctypes.util.find_library("lzo2")
        if _library_name:
            _library = ctypes.CDLL(_library_name)
            _native_lzo = _library.lzo1x_decompress_safe
            _native_lzo.argtypes = [
                ctypes.POINTER(ctypes.c_ubyte),
                ctypes.c_size_t,
                ctypes.POINTER(ctypes.c_ubyte),
                ctypes.POINTER(ctypes.c_size_t),
                ctypes.c_void_p,
            ]
            _native_lzo.restype = ctypes.c_int
            _NATIVE_LZO = _native_lzo
    except (AttributeError, OSError, ValueError):
        # Pyodide and minimal Windows installations do not necessarily expose
        # a shared liblzo2.  The bounded Python decoder below is the portable
        # path and remains the browser implementation.
        _NATIVE_LZO = None

XRAY_MAGIC = 0xFFFFFFFF
XRAY_MAX_UNPACKED_SIZE = 512 * 1024 * 1024
XRAY_SUPPORTED_OUTER_VERSIONS = frozenset({3, 5, 6})
_NATIVE_LZO_MIN_STREAM = 64 * 1024


class XRayError(SaveError):
    """Raised when bytes do not form a supported X-Ray save container."""


def _fail(message: str) -> XRayError:
    return XRayError(f"X-Ray: {message}")


def _literal_length_prefix(length: int) -> bytes:
    if length <= 0:
        return b""
    if length <= 238:
        return bytes((17 + length,))

    value = length - 18
    prefix = bytearray((0,))
    while value > 255:
        prefix.append(0)
        value -= 255
    prefix.append(value)
    return bytes(prefix)


def lzo1x_compress(payload: bytes) -> bytes:
    """Encode ``payload`` as a valid raw LZO1X-1 stream.

    The encoder intentionally emits one literal run and the format's end
    marker.  It does not promise the same compressed bytes as the game's
    dictionary compressor; :class:`XRayContainer` preserves the original
    compressed stream for a no-op round-trip and uses this encoder only after
    an explicit edit.
    """

    data = bytes(payload)
    if not data:
        return b"\x11\x00\x00"
    return _literal_length_prefix(len(data)) + data + b"\x11\x00\x00"


def lzo1x_decompress(stream: bytes, expected_size: int) -> bytes:
    """Decode one raw LZO1X stream with strict input/output bounds."""

    if not isinstance(expected_size, int) or isinstance(expected_size, bool):
        raise _fail("распакованный размер должен быть целым числом")
    if expected_size < 0 or expected_size > XRAY_MAX_UNPACKED_SIZE:
        raise _fail(f"недопустимый распакованный размер: {expected_size}")

    data = bytes(stream)
    if len(data) < 3:
        raise _fail("поток LZO слишком короткий")

    if _NATIVE_LZO is not None and len(data) >= _NATIVE_LZO_MIN_STREAM:
        source = (ctypes.c_ubyte * len(data)).from_buffer_copy(data)
        target = (ctypes.c_ubyte * expected_size)()
        target_size = ctypes.c_size_t(expected_size)
        result = _NATIVE_LZO(
            source,
            len(data),
            target,
            ctypes.byref(target_size),
            None,
        )
        if result != 0:
            raise _fail(f"поток LZO отклонён native decoder: code={result}")
        if target_size.value != expected_size:
            raise _fail(
                f"native decoder вернул размер {target_size.value} вместо {expected_size}"
            )
        return bytes(target)

    ip = 0
    output = bytearray()
    state = 0
    bitstream_version = 0

    # Newer LZO streams may carry a two-byte bitstream marker.  The original
    # X-Ray streams normally use the legacy raw form, but accepting the marker
    # costs nothing and makes malformed-input handling explicit.
    if len(data) >= 5 and data[0] == 17:
        bitstream_version = data[1]
        ip = 2

    def read_u8() -> int:
        nonlocal ip
        if ip >= len(data):
            raise _fail("поток LZO обрезан")
        value = data[ip]
        ip += 1
        return value

    def read_u16() -> int:
        nonlocal ip
        if ip + 2 > len(data):
            raise _fail("поток LZO обрезан на смещении")
        value = struct.unpack_from("<H", data, ip)[0]
        ip += 2
        return value

    def copy_literals(length: int) -> None:
        nonlocal ip
        if length < 0 or ip + length > len(data):
            raise _fail("литеральный участок LZO обрезан")
        if len(output) + length > expected_size:
            raise _fail("распакованный размер превышает заголовок")
        output.extend(data[ip : ip + length])
        ip += length

    def copy_match(start: int, length: int) -> None:
        if length <= 0 or start < 0 or start >= len(output):
            raise _fail("некорректная обратная ссылка LZO")
        if len(output) + length > expected_size:
            raise _fail("распакованный размер превышает заголовок")
        distance = len(output) - start
        # Matches may overlap the write cursor.  Materialising one copy of the
        # already-emitted distance window and repeating it is equivalent to the
        # byte-at-a-time LZ rule, while keeping large real saves practical in
        # the desktop detector and Pyodide browser build.
        pattern = bytes(output[start : start + distance])
        repetitions = (length + distance - 1) // distance
        output.extend((pattern * repetitions)[:length])

    # A first command above 17 is a literal run encoded as 17 + length.  A
    # short run (<4) is followed by the normal match/literal state transition.
    if ip < len(data) and data[ip] > 17:
        first = read_u8() - 17
        copy_literals(first)
        state = first if first < 4 else 4

    while True:
        command = read_u8()

        if command < 16:
            if state == 0:
                length = command
                if length == 0:
                    zeroes = 0
                    while read_u8() == 0:
                        zeroes += 1
                        if zeroes > (XRAY_MAX_UNPACKED_SIZE // 255) + 1:
                            raise _fail("слишком длинный литеральный участок")
                    length = zeroes * 255 + 15 + data[ip - 1]
                copy_literals(length + 3)
                state = 4
                continue

            next_literals = command & 3
            if state != 4:
                match_start = len(output) - 1 - (command >> 2) - (read_u8() << 2)
                copy_match(match_start, 2)
            else:
                match_start = len(output) - (1 + 0x0800) - (command >> 2) - (read_u8() << 2)
                length = 3

            copy_literals(next_literals)
            state = next_literals
            continue

        if command >= 64:
            next_literals = command & 3
            match_start = len(output) - 1 - ((command >> 2) & 7) - (read_u8() << 3)
            length = (command >> 5) + 1
        elif command >= 32:
            length = (command & 31) + 2
            if length == 2:
                zeroes = 0
                while read_u8() == 0:
                    zeroes += 1
                    if zeroes > (XRAY_MAX_UNPACKED_SIZE // 255) + 1:
                        raise _fail("слишком длинная match-длина")
                length += zeroes * 255 + 31 + data[ip - 1]
            encoded = read_u16()
            match_start = len(output) - 1 - (encoded >> 2)
            next_literals = encoded & 3
        else:
            if ip + 2 > len(data):
                raise _fail("поток LZO обрезан на смещении")
            encoded = struct.unpack_from("<H", data, ip)[0]
            next_literals = encoded & 3

            # This optional extension is part of LZO1X bitstream versions that
            # advertise zero runs.  X-Ray does not use it, but rejecting a
            # truncated extension is safer than interpreting it as a match.
            if bitstream_version and (encoded & 0xFFFC) == 0xFFFC and (command & 0xF8) == 0x18:
                read_u16()
                if ip >= len(data):
                    raise _fail("zero-run extension LZO обрезан")
                length = (command & 7) | (read_u8() << 3)
                length += 4
                if len(output) + length > expected_size:
                    raise _fail("нулевой участок превышает размер payload")
                output.extend(b"\x00" * length)
                copy_literals(next_literals)
                state = next_literals
                continue

            length = (command & 7) + 2
            if length == 2:
                zeroes = 0
                while read_u8() == 0:
                    zeroes += 1
                    if zeroes > (XRAY_MAX_UNPACKED_SIZE // 255) + 1:
                        raise _fail("слишком длинная match-длина")
                length += zeroes * 255 + 7 + data[ip - 1]

            encoded = read_u16()
            next_literals = encoded & 3
            if (command & 8) == 0:
                match_start = len(output) - (encoded >> 2)
                if match_start == len(output):
                    if length != 3:
                        raise _fail("неверный LZO end marker")
                    if ip != len(data):
                        raise _fail("после LZO end marker остались байты")
                    break
            else:
                match_start = len(output) - ((command & 8) << 11) - (encoded >> 2)
            match_start -= 0x4000

        copy_match(match_start, length)
        copy_literals(next_literals)
        state = next_literals

    if len(output) != expected_size:
        raise _fail(
            f"неверный размер после распаковки: {len(output)} вместо {expected_size}"
        )
    return bytes(output)


@dataclass(frozen=True)
class XRayChunk:
    """One top-level ``u32 type, u32 size, bytes`` payload chunk."""

    type: int
    offset: int
    size: int
    data: bytes

    @property
    def end(self) -> int:
        return self.offset + 8 + self.size


def parse_chunks(raw: bytes) -> tuple[XRayChunk, ...]:
    """Parse all top-level chunks and reject truncation or trailing bytes."""

    payload = bytes(raw)
    chunks: list[XRayChunk] = []
    offset = 0
    while offset < len(payload):
        if len(payload) - offset < 8:
            raise _fail(f"chunk header обрезан на смещении 0x{offset:X}")
        chunk_type, size = struct.unpack_from("<II", payload, offset)
        data_start = offset + 8
        data_end = data_start + size
        if data_end > len(payload):
            raise _fail(
                f"chunk type={chunk_type} обрезан: конец 0x{data_end:X}, "
                f"payload заканчивается на 0x{len(payload):X}"
            )
        chunks.append(XRayChunk(chunk_type, offset, size, payload[data_start:data_end]))
        offset = data_end
    if not chunks:
        raise _fail("payload не содержит chunks")
    return tuple(chunks)


@dataclass(frozen=True)
class XRayContainer:
    """Validated original X-Ray container with a lossless no-op builder."""

    original: bytes
    magic: int
    version: int
    unpacked_size: int
    raw: bytes
    chunks: tuple[XRayChunk, ...]

    @classmethod
    def from_bytes(cls, data: bytes) -> XRayContainer:
        original = bytes(data)
        if len(original) < 12:
            raise _fail("заголовок короче 12 байт")

        magic, version, unpacked_size = struct.unpack_from("<III", original, 0)
        if magic != XRAY_MAGIC:
            raise _fail(f"неверная сигнатура 0x{magic:08X}, ожидалось 0xFFFFFFFF")
        if version not in XRAY_SUPPORTED_OUTER_VERSIONS:
            supported = ", ".join(str(value) for value in sorted(XRAY_SUPPORTED_OUTER_VERSIONS))
            raise _fail(f"неподдерживаемая версия контейнера {version}; поддерживаются {supported}")
        if unpacked_size <= 0 or unpacked_size > XRAY_MAX_UNPACKED_SIZE:
            raise _fail(f"недопустимый распакованный размер: {unpacked_size}")

        raw = lzo1x_decompress(original[12:], unpacked_size)
        chunks = parse_chunks(raw)
        return cls(original, magic, version, unpacked_size, raw, chunks)

    @property
    def chunk_types(self) -> tuple[int, ...]:
        return tuple(chunk.type for chunk in self.chunks)

    def build(self, raw: bytes | None = None) -> bytes:
        """Return original bytes for a no-op, or a valid rebuilt container."""

        if raw is None or bytes(raw) == self.raw:
            return self.original
        payload = bytes(raw)
        if not payload or len(payload) > XRAY_MAX_UNPACKED_SIZE:
            raise _fail(
                f"изменённый payload имеет недопустимый размер {len(payload)}"
            )
        parse_chunks(payload)
        return struct.pack("<III", self.magic, self.version, len(payload)) + lzo1x_compress(payload)


__all__ = [
    "XRAY_MAGIC",
    "XRAY_MAX_UNPACKED_SIZE",
    "XRAY_SUPPORTED_OUTER_VERSIONS",
    "XRayChunk",
    "XRayContainer",
    "XRayError",
    "lzo1x_compress",
    "lzo1x_decompress",
    "parse_chunks",
]

